WITH filtered_payments AS (SELECT *, CONCAT_WS(',', method, status) AS method_status_key FROM payments WHERE paid_at < '2024-09-01'), payments_stats AS (SELECT status, COUNT(CASE WHEN method = 'promptpay' THEN 1 END) AS promptpay_count, COUNT(*) AS row_count FROM filtered_payments GROUP BY status) SELECT status, promptpay_count, row_count FROM payments_stats WHERE promptpay_count < 5;
